"""有界匹配存储(≤预算字节): 20B/行; 全串行永不裁 / 前缀行可裁; 载入>0.70 触发裁剪"""
from array import array

M64 = (1 << 64) - 1
REC = 20


class MatchStore:
    def __init__(self, budget_bytes=200 * 1024 * 1024):
        cap = 1
        while (cap << 1) * REC <= budget_bytes:
            cap <<= 1
        self.cap = cap
        self.mask = cap - 1
        self.k1 = array("Q", bytes(8 * cap))
        self.k2 = array("Q", bytes(8 * cap))
        self.act = bytearray(cap)
        self.kind = bytearray(cap)
        self.hits = array("H", bytes(2 * cap))
        self.used = 0
        self.tombs = 0
        self.stat = {"inserts": 0, "updates": 0, "pruned_prefix": 0, "saturated": 0, "prunes": 0}

    def _hash(self, k):
        x = ((k & M64) ^ ((k >> 64) & M64) ^ (k >> 7)) & M64
        x ^= x >> 33
        x = (x * 0xFF51AFD7ED558CCD) & M64
        x ^= x >> 33
        return x & self.mask

    def _eq(self, i, k):
        return self.k1[i] == (k & M64) and self.k2[i] == ((k >> 64) & M64)

    def _put(self, i, k):
        self.k1[i] = k & M64
        self.k2[i] = (k >> 64) & M64

    def _slot(self, k):
        i = self._hash(k)
        first_tomb = -1
        for _ in range(self.cap):
            kd = self.kind[i]
            if kd == 0:
                return (first_tomb if first_tomb >= 0 else i), False, False
            if kd == 3:
                if first_tomb < 0:
                    first_tomb = i
            elif self._eq(i, k):
                return i, True, False
            i = (i + 1) & self.mask
        return -1, False, True

    def get(self, k):
        i, found, _ = self._slot(k)
        if not found:
            return -1
        if self.hits[i] < 65535:
            self.hits[i] += 1
        return self.act[i]

    def get2(self, k):
        i, found, _ = self._slot(k)
        return None if not found else {"action": self.act[i], "kind": self.kind[i]}

    def delete(self, k):
        i, found, _ = self._slot(k)
        if not found:
            return False
        self.kind[i] = 3
        self.tombs += 1
        self.used -= 1
        return True

    def set(self, k, action, kind):
        i, found, _ = self._slot(k)
        if found:
            self.stat["updates"] += 1
            return i
        if i == -1:
            self.stat["saturated"] += 1
            return -1
        if self.kind[i] == 0 and (self.used + 1) / self.cap > 0.70:
            self.prune()
            i, found, _ = self._slot(k)
            if found:
                self.stat["updates"] += 1
                return i
            if i == -1:
                self.stat["saturated"] += 1
                return -1
        if self.kind[i] == 0:
            self.used += 1
        elif self.kind[i] == 3:
            self.tombs -= 1
        self._put(i, k)
        self.act[i] = action
        self.kind[i] = kind
        self.hits[i] = 0
        self.stat["inserts"] += 1
        return i

    def prune(self):
        self.stat["prunes"] += 1
        target = int(self.cap * 0.60)
        dropped = 0
        for i in range(self.cap):
            if self.used <= target:
                break
            if self.kind[i] == 2 and self.hits[i] == 0:
                self.kind[i] = 3
                self.tombs += 1
                self.used -= 1
                dropped += 1
        while self.used > target:
            li, lh = -1, 65536
            for i in range(self.cap):
                if self.kind[i] == 2 and self.hits[i] < lh:
                    lh, li = self.hits[i], i
            if li < 0:
                self.stat["saturated"] += 1
                break
            self.kind[li] = 3
            self.tombs += 1
            self.used -= 1
            dropped += 1
        self.stat["pruned_prefix"] += dropped
        return dropped

    def stats(self):
        full = sum(1 for i in range(self.cap) if self.kind[i] == 1)
        pref = sum(1 for i in range(self.cap) if self.kind[i] == 2)
        return {"cap": self.cap, "bytes": self.cap * REC, "used": self.used,
                "full": full, "prefix": pref, "load": round(self.used / self.cap, 3), **self.stat}
